def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version from pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, core_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or a list of identifiers
        # A version without pre-release sorts after one with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release is greater
        if pre2 is None:
            return -1  # version with pre-release is less

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                if int(id1) < int(id2):
                    return -1
                elif int(id1) > int(id2):
                    return 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(version):
        parsed = parse_version(version)
        major, minor, patch, prerelease = parsed

        # Create a tuple for sorting
        # (major, minor, patch, prerelease_sort_key)
        if prerelease is None:
            # No pre-release: sorts after any version with pre-release
            prerelease_sort_key = (1,)
        else:
            # Has pre-release: sorts before version without pre-release
            prerelease_sort_key = (0, prerelease)

        return (major, minor, patch, prerelease_sort_key)

    # Stable sort with index to maintain input order for equal precedence
    indexed_versions = [(version, index) for index, version in enumerate(versions)]

    def compare_versions(item):
        version, index = item
        return (sort_key(version), index)

    sorted_items = sorted(indexed_versions, key=compare_versions)
    return [version for version, index in sorted_items]

